    let slots = state.compute_availability(q.calendar_id, &q.from, &q.to).await;
    (StatusCode::OK, Json(serde_json::json!({ "slots": slots }))).into_response()
}

/// GET /internal/event?calendar_id=&event_id=
#[derive(Deserialize)]
struct EventGetQuery {
    calendar_id: i64,
