const { MockOAuthProvider, signJwt, s256Challenge } = require('./mcp-acceptance/mock/oauth-provider.js');
const p = new MockOAuthProvider({ issuer: 'http://127.0.0.1:9999', resource: 'http://127.0.0.1:9998/mcp', redirect: 'http://127.0.0.1:8321/callback' });
const reg = p.handleRegister({ client_name: 't', redirect_uris: ['http://127.0.0.1:8321/callback'], grant_types: ['authorization_code','refresh_token'], response_types: ['code'], token_endpoint_auth_method: 'none' });
const cid = reg.body.client_id;
const params = new URLSearchParams({ response_type: 'code', client_id: cid, redirect_uri: 'http://127.0.0.1:8321/callback', scope: 'commoncal.calendar.metadata.read', state: 'xyz', code_challenge: s256Challenge('verifier-abc'), code_challenge_method: 'S256' });
const auth = p.handleAuthorize(params);
const code = new URL(auth.location, 'http://x').searchParams.get('code');
const tokParams = new URLSearchParams({ grant_type: 'authorization_code', code, redirect_uri: 'http://127.0.0.1:8321/callback', client_id: cid, code_verifier: 'verifier-abc' });
const tok = p.handleToken(tokParams);
const at = tok.body.access_token;
const v = p.validateAccessToken(at);
console.log('VALIDATE ok', v.ok, 'sub', v.claims.sub, 'client_id', v.claims.client_id, 'scope', v.claims.scope);
const bad = signJwt({ iss: 'http://evil', sub: '1', aud: 'http://127.0.0.1:9998/mcp', exp: Math.floor(Date.now()/1000)+300, iat: Math.floor(Date.now()/1000), client_id: cid, scope: 'x' }, p.signingKey);
console.log('WRONG ISSUER ok', p.validateAccessToken(bad).ok, 'err', p.validateAccessToken(bad).error);
const parts = at.split('.');
const badSig = parts[0] + '.' + parts[1] + '.' + Buffer.from('garbage').toString('base64url');
console.log('BAD SIG ok', p.validateAccessToken(badSig).ok, 'err', p.validateAccessToken(badSig).error);
const exp = signJwt({ iss: 'http://127.0.0.1:9999', sub: '1', aud: 'http://127.0.0.1:9998/mcp', exp: Math.floor(Date.now()/1000)-100, iat: Math.floor(Date.now()/1000)-400, client_id: cid, scope: 'x' }, p.signingKey);
console.log('EXPIRED ok', p.validateAccessToken(exp).ok, 'err', p.validateAccessToken(exp).error);
const badAud = signJwt({ iss: 'http://127.0.0.1:9999', sub: '1', aud: 'http://evil/mcp', exp: Math.floor(Date.now()/1000)+300, iat: Math.floor(Date.now()/1000), client_id: cid, scope: 'x' }, p.signingKey);
console.log('WRONG AUD ok', p.validateAccessToken(badAud).ok, 'err', p.validateAccessToken(badAud).error);
const badClient = signJwt({ iss: 'http://127.0.0.1:9999', sub: '1', aud: 'http://127.0.0.1:9998/mcp', exp: Math.floor(Date.now()/1000)+300, iat: Math.floor(Date.now()/1000), client_id: 'unknown-client', scope: 'x' }, p.signingKey);
console.log('UNKNOWN CLIENT ok', p.validateAccessToken(badClient).ok, 'err', p.validateAccessToken(badClient).error);
console.log('ALL CRYPTO TESTS DONE');
"

